// Visual explainers for the Networking roadmap. Schema: CONTRIBUTING.md → "Visuals".
'use strict';

// ===== Module 1: Network Models ==============================================

registerDiagram({
  id: 'net-osi-layers',
  roadmap: 'networking', module: 1, topic: 'The OSI Model: 7 Layers, PDUs, Protocols & Devices',
  kind: 'graph',
  title: 'OSI vs TCP/IP: layers, PDUs and the devices that work at each one',
  desc: 'OSI is the vocabulary (seven layers); TCP/IP is what is actually implemented (four layers). The right column shows which boxes in a real network act at each layer, which decides what they can see and decide on.',
  groups: [
    { id: 'osi', label: 'OSI reference model', x: 0, y: 0, w: 2, h: 7, color: 'blue' },
    { id: 'tcpip', label: 'TCP/IP (implemented)', x: 2.5, y: 0, w: 1.5, h: 7, color: 'green' },
    { id: 'dev', label: 'Devices and components', x: 4.5, y: 0, w: 2.5, h: 7, color: 'orange' },
  ],
  nodes: [
    { id: 'o7', label: '7 Application', sub: 'PDU: data · HTTP, gRPC, DNS, SSH', x: 0, y: 0, w: 2, color: 'blue' },
    { id: 'o6', label: '6 Presentation', sub: 'TLS (by convention), encoding', x: 0, y: 1, w: 2, color: 'blue' },
    { id: 'o5', label: '5 Session', sub: 'session setup / teardown', x: 0, y: 2, w: 2, color: 'blue' },
    { id: 'o4', label: '4 Transport', sub: 'PDU: segment / datagram · TCP, UDP', x: 0, y: 3, w: 2, color: 'blue' },
    { id: 'o3', label: '3 Network', sub: 'PDU: packet · IPv4, IPv6, ICMP', x: 0, y: 4, w: 2, color: 'blue' },
    { id: 'o2', label: '2 Data link', sub: 'PDU: frame · Ethernet, ARP, VLAN', x: 0, y: 5, w: 2, color: 'blue' },
    { id: 'o1', label: '1 Physical', sub: 'PDU: bits · copper, fibre, radio', x: 0, y: 6, w: 2, color: 'blue' },
    { id: 'tApp', label: 'Application', sub: 'HTTP, TLS, DNS, gRPC', x: 2.5, y: 0, w: 1.5, h: 3, color: 'green', info: 'TCP/IP folds OSI layers 5, 6 and 7 into one Application layer. On Linux this layer lives in your process (user space); TLS is a library in the process unless kTLS offloads the record layer to the kernel.' },
    { id: 'tTr', label: 'Transport', sub: 'TCP, UDP (QUIC on UDP)', x: 2.5, y: 3, w: 1.5, color: 'green', info: 'Ports, reliability, ordering and congestion control. TCP and UDP live in the kernel. QUIC implements a reliable transport in user space on top of UDP, which is why it can evolve faster than kernel TCP.' },
    { id: 'tIn', label: 'Internet', sub: 'IPv4, IPv6, ICMP', x: 2.5, y: 4, w: 1.5, color: 'green', info: 'The narrow waist of the hourglass: many link types below and many applications above, but one IP layer in the middle. Routers only need to understand this layer.' },
    { id: 'tLk', label: 'Link', sub: 'Ethernet, Wi-Fi, ARP', x: 2.5, y: 5, w: 1.5, h: 2, color: 'green', info: 'Also called Network Access. It merges OSI layers 1 and 2. Many engineers reason with a 5-layer hybrid that splits it back into Data link and Physical.' },
    { id: 'd7', label: 'L7 LB, API gateway, WAF', sub: 'ALB, Envoy, Nginx (http), Kong', x: 4.5, y: 0, w: 2.5, color: 'orange', info: 'L7 components parse the whole request (method, path, headers, cookies, body), so they can route per request, retry, authenticate and rate limit. To do that they must terminate TLS or receive plaintext.' },
    { id: 'd6', label: 'TLS terminator', sub: 'often the same box as the L7 LB', x: 4.5, y: 1, w: 2.5, color: 'orange' },
    { id: 'd5', label: '(rarely a separate box)', sub: 'RPC sessions live in the app', x: 4.5, y: 2, w: 2.5, color: 'gray', ghost: true },
    { id: 'd4', label: 'L4 LB, stateful firewall, NAT', sub: 'AWS NLB, IPVS, conntrack', x: 4.5, y: 3, w: 2.5, color: 'orange', info: 'Sees IPs, ports and TCP flags but not the request. Balances whole connections, is protocol-agnostic and very fast, and can pass TLS through untouched.' },
    { id: 'd3', label: 'Router, L3 switch', sub: 'route tables, ECMP, anycast', x: 4.5, y: 4, w: 2.5, color: 'orange', info: 'Forwards by destination IP using longest-prefix match. A router decapsulates only up to L3, decrements TTL (recomputing the IPv4 checksum) and re-encapsulates with a new L2 header for the next hop. It may also re-mark DSCP or set ECN CE under congestion; NAT devices rewrite addresses and ports.' },
    { id: 'd2', label: 'Switch, bridge, NIC', sub: 'MAC learning, VLAN trunks', x: 4.5, y: 5, w: 2.5, color: 'orange' },
    { id: 'd1', label: 'Cable, transceiver, hub', sub: 'signals on the medium', x: 4.5, y: 6, w: 2.5, color: 'orange' },
  ],
  edges: [],
  steps: [
    { caption: 'Layer 7 is where HTTP, gRPC and DNS live. A component working here sees the full request (method, path, headers), so it can route on the Host header or a URL path. That visibility is what "L7 load balancer" means.', active: ['o7', 'tApp', 'd7'] },
    { caption: 'Layers 6 and 5 are fuzzy in practice. TLS sits between TCP and HTTP and gets called L6, L4.5 or part of L7. TCP/IP simply folds 5, 6 and 7 into one Application layer. Saying this out loud in an interview shows you know the model is only a model.', active: ['o6', 'o5', 'tApp', 'd6', 'd5'] },
    { caption: 'Layer 4 adds ports, so it can tell connections apart. An L4 load balancer or stateful firewall tracks 5-tuples but cannot read a URL. QUIC is a transport too, built on UDP datagrams.', active: ['o4', 'tTr', 'd4'] },
    { caption: 'Layer 3 moves packets between networks using IP addresses. Routers pick the next hop by longest-prefix match and decrement TTL. BGP runs over TCP port 179 but exists to serve layer 3 routing.', active: ['o3', 'tIn', 'd3'] },
    { caption: 'Layer 2 delivers frames inside one broadcast domain using MAC addresses. Switches learn which MAC is on which port; ARP maps an IP to a MAC; an 802.1Q tag puts a frame in a VLAN.', active: ['o2', 'tLk', 'd2'] },
    { caption: 'Layer 1 is the bits on copper, fibre or radio. Faults here show up as CRC errors, link flaps or a negotiated speed lower than expected.', active: ['o1', 'tLk', 'd1'] },
    { caption: 'Where the code runs: on Linux, L2 to L4 are in the kernel and L7 is in your process. QUIC moves the transport into user space, so it ships with the application instead of waiting for kernel upgrades.', active: ['tApp', 'tTr', 'tIn', 'tLk'] },
  ],
});

registerDiagram({
  id: 'net-encapsulation',
  roadmap: 'networking', module: 1, topic: 'Encapsulation & Decapsulation',
  kind: 'graph',
  title: 'Encapsulation: each layer wraps the one above (and eats MTU)',
  desc: 'Press Play to watch an HTTPS request gain a header at every layer on the way down, get rewritten at a router hop, wrapped again by an overlay, and unwrapped at the receiver. Header sizes are the ones that drive MTU and MSS math.',
  nodes: [
    { id: 'd0', label: 'HTTP request', sub: 'L7 data, e.g. 1,200 B', x: 3, y: 0, w: 2, color: 'purple', info: 'The application only ever writes bytes into a socket. It never sees any of the headers added below it.' },
    { id: 'tls', label: 'TLS', sub: '5 B hdr', x: 2.25, y: 1, w: 0.75, color: 'teal', enter: 2 },
    { id: 'd1', label: 'encrypted HTTP', sub: 'AEAD ciphertext', x: 3, y: 1, w: 2, color: 'teal', enter: 2 },
    { id: 'tag', label: 'tag', sub: '16 B + 1', x: 5, y: 1, w: 0.75, color: 'teal', enter: 2, info: 'TLS 1.3 adds a 16-byte AEAD authentication tag plus 1 byte for the inner content type to every record. A record holds at most 16 KB of plaintext.' },
    { id: 'tcp', label: 'TCP', sub: '20 B (32)', x: 1.5, y: 2, w: 0.75, color: 'green', enter: 3, info: 'Source and destination port, sequence and acknowledgement numbers, window, flags and options. Linux adds the 12-byte timestamps option by default, so 32 bytes is typical.' },
    { id: 'd2', label: 'TLS record bytes', sub: 'TCP payload ≤ MSS 1460 B', x: 2.25, y: 2, w: 3.5, color: 'green', enter: 3 },
    { id: 'ip', label: 'IPv4', sub: '20 B', x: 0.75, y: 3, w: 0.75, color: 'blue', enter: 4, info: 'Source and destination IP, TTL, protocol number (6 = TCP, 17 = UDP), the DF bit and a header checksum. IPv6 uses a fixed 40-byte header and has no checksum.' },
    { id: 'd3', label: 'TCP segment', sub: 'IP payload ≤ 1480 B', x: 1.5, y: 3, w: 4.25, color: 'blue', enter: 4 },
    { id: 'eth', label: 'Ethernet', sub: '14 B', x: 0, y: 4, w: 0.75, color: 'orange', enter: 5, info: 'Destination MAC, source MAC and EtherType (0x0800 = IPv4, 0x86DD = IPv6). An 802.1Q VLAN tag adds 4 more bytes.' },
    { id: 'd4', label: 'IP packet', sub: 'Ethernet payload ≤ MTU 1500 B', x: 0.75, y: 4, w: 5, color: 'orange', enter: 5 },
    { id: 'fcs', label: 'FCS', sub: '4 B', x: 5.75, y: 4, w: 0.75, color: 'orange', enter: 5 },
    { id: 'vx', label: 'VXLAN outer', sub: '+50 B: Eth·IP·UDP·VXLAN', x: 0, y: 5, w: 1.5, color: 'red', enter: 7, exit: 8, info: 'Outer Ethernet 14 + outer IPv4 20 + UDP 8 + VXLAN 8 = 50 bytes. WireGuard costs 60 (IPv4) or 80 (IPv6) bytes and IPsec roughly 73. Every tunnel is just a packet inside a packet.' },
    { id: 'd5', label: 'original Ethernet frame', sub: 'inner MTU must drop to 1450', x: 1.5, y: 5, w: 5, color: 'red', enter: 7, exit: 8 },
  ],
  edges: [
    { from: 'd0', to: 'd1' },
    { from: 'd1', to: 'd2' },
    { from: 'd2', to: 'd3' },
    { from: 'd3', to: 'd4' },
    { from: 'd4', to: 'd5' },
  ],
  steps: [
    { caption: 'The application writes an HTTP request into a TLS connection. From here down, the TLS library and the kernel add every header; the application never handles them.', active: ['d0'] },
    { caption: 'TLS encrypts the bytes into a record: a 5-byte header, the ciphertext, and a 16-byte AEAD tag plus 1 content-type byte. Record boundaries have nothing to do with packet boundaries.', flows: [{ from: 'd0', to: 'd1', label: 'encrypt' }], active: ['tls', 'tag'] },
    { caption: 'TCP slices the byte stream into segments no larger than the MSS and adds a 20-byte header (32 with timestamps): ports, sequence numbers, window. MSS = 1500 MTU − 20 IP − 20 TCP = 1460 bytes.', flows: [{ from: 'd1', to: 'd2', label: 'segment' }], active: ['tcp'] },
    { caption: 'IP adds 20 bytes (IPv6: 40) with the source and destination address, TTL and the DF bit. The whole packet must fit the link MTU of 1500 bytes, or it is fragmented or dropped.', flows: [{ from: 'd2', to: 'd3', label: 'add IP header' }], active: ['ip'] },
    { caption: 'Ethernet adds 14 bytes plus a 4-byte FCS trailer. The destination MAC is the next hop (usually the default gateway, found with ARP), not the final server. On the wire that is 1518 bytes plus preamble and gap.', flows: [{ from: 'd3', to: 'd4', label: 'frame' }], active: ['eth', 'fcs'] },
    { caption: 'Each router hop strips the Ethernet header, decrements TTL, recomputes the IPv4 checksum and adds a fresh Ethernet header. It may also re-mark DSCP, set ECN to CE when congested, or fragment if DF is clear; NAT rewrites addresses and ports.', active: ['eth', 'ip', 'fcs', 'd4'] },
    { caption: 'An overlay (VXLAN in many Kubernetes CNIs) wraps the whole frame in another 50 bytes of headers. If the pod MTU stays at 1500, the outer packet is 1550 and gets dropped: set the inner MTU to 1450 or clamp MSS.', flows: [{ from: 'd4', to: 'd5', label: 'encapsulate' }], active: ['vx'] },
    { caption: 'The receiver decapsulates bottom-up. Each header names the next handler: EtherType says IP, the IP protocol field says TCP, the port picks the socket, then TLS decrypts and HTTP parses.', flows: [{ from: 'd4', to: 'd3', label: 'strip Ethernet' }, { from: 'd2', to: 'd1', label: 'strip TCP' }, { from: 'd1', to: 'd0', label: 'decrypt' }] },
  ],
});

registerDiagram({
  id: 'net-pmtud',
  roadmap: 'networking', module: 1, topic: 'MTU, MSS, Fragmentation & Path MTU Discovery',
  kind: 'sequence',
  title: 'Path MTU discovery, the ICMP black hole, and MSS clamping',
  desc: 'The handshake and small requests work, but large responses hang. This is the classic symptom of a PMTUD black hole: a smaller-MTU hop (here a VPN tunnel) needs ICMP to reach the sender, and a firewall drops it.',
  actors: [
    { id: 'c', label: 'Client', sub: 'MTU 1500', icon: '💻', color: 'gray' },
    { id: 'gw', label: 'VPN gateway', sub: 'tunnel MTU 1400', icon: '🔐', color: 'orange', info: 'The tunnel adds encapsulation overhead, so the usable MTU inside it is smaller than 1500. WireGuard defaults to 1420; IPsec and VXLAN paths are smaller still.' },
    { id: 'fw', label: 'Firewall', sub: 'in front of server', icon: '🧱', color: 'red', info: 'A rule such as "drop all ICMP" looks like hardening but breaks PMTUD. Allow ICMP type 3 code 4 (Fragmentation Needed) and ICMPv6 type 2 (Packet Too Big).' },
    { id: 's', label: 'Server', sub: 'MTU 1500', icon: '🖥️', color: 'green' },
  ],
  steps: [
    { section: 'Handshake: MSS comes from each local MTU' },
    { from: 'c', to: 's', label: 'SYN, MSS=1460', caption: 'Each side advertises an MSS based on its own interface MTU (1500 − 40 = 1460). Neither knows about the 1400-byte tunnel in the middle.' },
    { from: 's', to: 'c', label: 'SYN-ACK, MSS=1460', reply: true, caption: 'Both sides agree on 1460-byte segments. The handshake packets are tiny, so they cross the tunnel without trouble.' },
    { from: 'c', to: 's', label: 'GET /report (300 B)', caption: 'Small requests and responses also fit. Everything looks healthy so far.' },
    { section: 'PMTUD working' },
    { from: 's', to: 'gw', label: '1500 B packet, DF=1', caption: 'The server sends a full-size packet with Don\'t Fragment set. Linux sets DF on TCP by default so that it can discover the path MTU instead of relying on fragmentation.' },
    { from: 'gw', to: 'gw', label: 'too big for 1400', caption: 'The gateway cannot forward 1500 bytes into a 1400-byte tunnel and is not allowed to fragment, so it drops the packet. IPv6 routers never fragment at all; only the source can.' },
    { from: 'gw', to: 's', label: 'ICMP Frag Needed, MTU=1400', reply: true, caption: 'It returns ICMP type 3 code 4 (IPv6: Packet Too Big) carrying the next-hop MTU back to the sender.' },
    { from: 's', to: 's', label: 'PMTU = 1400', caption: 'The server caches the path MTU for this destination and re-sends smaller segments. The user notices nothing.' },
    { from: 's', to: 'c', label: '1400 B packets fit', caption: 'Large responses now flow through the tunnel.' },
    { section: 'Black hole: ICMP filtered' },
    { from: 's', to: 'gw', label: '1500 B packet, DF=1', caption: 'Same situation on a different path, but this time the ICMP message has to cross a firewall that drops all ICMP.' },
    { from: 'gw', to: 'fw', label: 'ICMP Frag Needed', reply: true, caption: 'The gateway does the right thing and reports the smaller MTU.' },
    { from: 'fw', to: 'fw', label: 'drop all ICMP', caption: 'The firewall silently discards it, so the server never learns that its packets are too big.' },
    { from: 's', to: 's', label: 'RTO: resend 1500 B', caption: 'The server times out and retransmits the same oversized packet with exponential backoff. Every retry is dropped at the tunnel.' },
    { from: 'c', to: 'c', label: 'response hangs', caption: 'The client sees the connection open and then stall forever on large responses: "small API calls work over VPN, large responses hang".' },
    { section: 'Fix: MSS clamping on the tunnel' },
    { from: 'gw', to: 's', label: 'SYN, MSS clamped to 1360', caption: 'The gateway rewrites the MSS option in SYNs passing through (iptables --clamp-mss-to-pmtu) to 1400 − 40 = 1360, so TCP never builds packets that are too big. Also: allow ICMP, lower the CNI MTU, or enable tcp_mtu_probing.' },
    { from: 's', to: 'c', label: '1360 B payloads fit', caption: 'Clamping works without any ICMP. It only helps TCP, though; UDP and QUIC traffic still need a correct MTU or their own probing.' },
  ],
});

// ===== Module 2: IP Addressing & Routing =====================================

registerDiagram({
  id: 'net-nat-pat',
  roadmap: 'networking', module: 2, topic: 'Private Ranges, NAT & PAT',
  kind: 'graph',
  title: 'PAT: many private hosts share one public IP via the translation table',
  desc: 'A NAT gateway rewrites the source of outbound packets to its public IP and a free port, and remembers the mapping so replies can be translated back. Ports are the scarce resource, which is where most NAT outages come from.',
  groups: [
    { id: 'priv', label: 'Private subnets', x: 0, y: 0, w: 1, h: 5, color: 'gray' },
    { id: 'pub', label: 'Public subnet', x: 2.5, y: 2, w: 1.5, h: 3, color: 'blue' },
  ],
  nodes: [
    { id: 'h1', label: 'App 10.0.1.5', sub: 'RFC 1918 address', x: 0, y: 0, color: 'gray' },
    { id: 'h2', label: 'App 10.0.1.6', sub: 'RFC 1918 address', x: 0, y: 2, color: 'gray' },
    { id: 'h3', label: 'Pod 10.0.2.9', sub: 'busy HTTP client', x: 0, y: 4, color: 'gray' },
    { id: 'nat', label: 'NAT gateway', sub: 'public 203.0.113.10', x: 2.5, y: 2, w: 1.5, color: 'blue', info: 'Examples: a home router, AWS NAT Gateway, or a Kubernetes node masquerading pod egress traffic. It performs SNAT: the source address (and with PAT, the source port) is rewritten on the way out.' },
    { id: 'tbl', label: 'Translation table', sub: 'conntrack, 350 s idle', x: 2.5, y: 4, w: 1.5, shape: 'db', color: 'teal', info: 'Each entry maps (private IP, private port) to (public IP, public port) for one destination. On Linux this is conntrack; "nf_conntrack: table full, dropping packet" in dmesg means it ran out. AWS NAT Gateway expires idle TCP entries after 350 s.' },
    { id: 'srv', label: 'API server', sub: '198.51.100.20:443', x: 5, y: 2, color: 'green' },
  ],
  edges: [
    { from: 'h1', to: 'nat' },
    { from: 'h2', to: 'nat' },
    { from: 'h3', to: 'nat' },
    { from: 'nat', to: 'tbl', both: true, dashed: true, label: 'lookup / insert' },
    { from: 'nat', to: 'srv', label: 'SNAT: 203.0.113.10' },
  ],
  steps: [
    { caption: 'A private host opens a connection from 10.0.1.5:40000. RFC 1918 addresses are not routed on the Internet, so the subnet route table sends 0.0.0.0/0 to the NAT gateway.', flows: [{ from: 'h1', to: 'nat', label: '10.0.1.5:40000' }] },
    { caption: 'SNAT: the gateway rewrites the source to 203.0.113.10:1024 and stores the mapping. The server only ever sees the NAT IP, never the real client.', flows: [{ from: 'nat', to: 'tbl', label: 'insert :1024' }, { from: 'nat', to: 'srv', label: 'src …10:1024' }] },
    { caption: 'A second host happens to use the same source port 40000. PAT keeps the connections apart by giving it a different public port (1025). The port, not the IP, makes each mapping unique.', flows: [{ from: 'h2', to: 'nat', label: '10.0.1.6:40000' }, { from: 'nat', to: 'srv', label: 'src …10:1025' }] },
    { caption: 'A reply arrives for 203.0.113.10:1025. The gateway finds the entry and rewrites the destination back to 10.0.1.6:40000. Packets with no matching entry are dropped.', flows: [{ from: 'srv', to: 'nat', label: 'dst :1025' }, { from: 'nat', to: 'h2', label: '→ 10.0.1.6:40000' }], active: ['tbl'] },
    { caption: 'Port exhaustion: AWS NAT Gateway allows about 55,000 concurrent connections per unique destination (IP, port, protocol). A chatty client without keep-alive hits it and you see ErrorPortAllocation. Fix with pooling, more NAT IPs, or VPC endpoints for AWS APIs.', flows: [{ from: 'h3', to: 'nat', label: 'conn #55,001', color: 'red' }], active: ['tbl'] },
    { caption: 'Idle timeout: after 350 s without traffic the entry is gone. The next packet on that old connection gets a RST. Send TCP keep-alives more often than the NAT idle timeout on long-lived quiet connections.', flows: [{ from: 'h1', to: 'nat', label: 'after 6 min idle' }, { from: 'nat', to: 'h1', label: 'RST', color: 'red' }], active: ['tbl'] },
  ],
});

registerDiagram({
  id: 'net-anycast-bgp',
  roadmap: 'networking', module: 2, topic: 'BGP Basics & Anycast',
  kind: 'graph',
  title: 'Anycast with BGP: one prefix, many sites, failover by withdrawal',
  desc: 'Three PoPs announce the same prefix 192.0.2.0/24 from AS 64500. BGP gives every network a path to the topologically nearest PoP. Withdrawing a route moves traffic within seconds, and a bogus more-specific announcement steals it.',
  nodes: [
    { id: 'ueu', label: 'Users: Europe', icon: '👥', x: 0, y: 0, color: 'gray' },
    { id: 'uus', label: 'Users: US', icon: '👥', x: 3, y: 0, color: 'gray' },
    { id: 'uas', label: 'Users: Asia', icon: '👥', x: 6, y: 0, color: 'gray' },
    { id: 'teu', label: 'ISP AS 64501', sub: 'Europe', x: 0, y: 2, color: 'blue', info: 'Every AS keeps the best path per prefix chosen by policy: local preference first, then shortest AS_PATH, then other tie-breakers. Policy beats shortest path.' },
    { id: 'tus', label: 'ISP AS 64502', sub: 'US', x: 3, y: 2, color: 'blue' },
    { id: 'tas', label: 'ISP AS 64503', sub: 'Asia', x: 6, y: 2, color: 'blue' },
    { id: 'pfra', label: 'PoP Frankfurt', sub: 'AS 64500, /24', x: 0, y: 4, color: 'green', info: 'A local health checker announces the prefix only while the service on this PoP is healthy. Withdrawing the route is how a site takes itself out of rotation.' },
    { id: 'piad', label: 'PoP Virginia', sub: 'AS 64500, /24', x: 3, y: 4, color: 'green' },
    { id: 'psin', label: 'PoP Singapore', sub: 'AS 64500, /24', x: 6, y: 4, color: 'green' },
    { id: 'bad', label: 'AS 64666', sub: 'misconfig or hijack', x: 1.5, y: 3, color: 'red', ghost: true, enter: 6, info: 'Famous incidents: Pakistan Telecom announcing a YouTube /24 in 2008, and many accidental route leaks since. The opposite failure is Facebook in October 2021, whose DNS servers withdrew their own announcements and vanished from the Internet.' },
  ],
  edges: [
    { from: 'ueu', to: 'teu' },
    { from: 'uus', to: 'tus' },
    { from: 'uas', to: 'tas' },
    { from: 'teu', to: 'tus', both: true, label: 'peering' },
    { from: 'tus', to: 'tas', both: true, label: 'peering' },
    { from: 'teu', to: 'pfra', both: true, label: 'eBGP' },
    { from: 'tus', to: 'piad', both: true, label: 'eBGP' },
    { from: 'tas', to: 'psin', both: true, label: 'eBGP' },
    { from: 'bad', to: 'teu', dashed: true },
  ],
  steps: [
    { caption: 'Each PoP opens an eBGP session (TCP 179) to its upstream and announces the same prefix, 192.0.2.0/24, with origin AS 64500.', flows: [{ from: 'pfra', to: 'teu', label: 'announce /24' }, { from: 'piad', to: 'tus', label: 'announce /24' }, { from: 'psin', to: 'tas', label: 'announce /24' }] },
    { caption: 'Announcements propagate and every AS prepends itself to AS_PATH, which prevents loops. Each network now knows several paths to the same prefix and keeps the best one by policy, then by shortest AS_PATH.', flows: [{ from: 'teu', to: 'tus', label: 'path 64501 64500' }, { from: 'tus', to: 'tas', label: 'path 64502 64500' }] },
    { caption: 'Users everywhere query the same IP, yet each lands on a nearby PoP. This is how 1.1.1.1, 8.8.8.8 and the root DNS servers work, and why anycast absorbs DDoS: attack traffic is split across every site.', flows: [{ from: 'ueu', to: 'pfra', label: 'to 192.0.2.53' }, { from: 'uus', to: 'piad', label: 'to 192.0.2.53' }, { from: 'uas', to: 'psin', label: 'to 192.0.2.53' }] },
    { caption: 'Frankfurt fails its health check and withdraws the route. No DNS TTL is involved, so traffic moves as soon as BGP converges, usually within seconds.', flows: [{ from: 'pfra', to: 'teu', label: 'withdraw', color: 'red' }] },
    { caption: 'European traffic now follows the next-best path to Virginia: slower, but still answered. UDP DNS queries do not notice; TCP connections that were open to Frankfurt break and must reconnect.', flows: [{ from: 'ueu', to: 'teu', label: 'to 192.0.2.53' }, { from: 'teu', to: 'tus', label: 'next-best path' }, { from: 'tus', to: 'piad', label: 'served' }] },
    { caption: 'Hijack or leak: another AS announces 192.0.2.0/25. Longest-prefix match prefers the /25 wherever it propagates, so traffic goes to the wrong place. RPKI route origin validation lets networks drop announcements whose origin AS is not authorised.', flows: [{ from: 'bad', to: 'teu', label: 'announce /25', color: 'red' }] },
  ],
});

registerDiagram({
  id: 'net-arp-dhcp',
  roadmap: 'networking', module: 2, topic: 'Layer 2 Glue: MAC, ARP, DHCP & VLANs',
  kind: 'sequence',
  title: 'Joining a LAN: DHCP (DORA), then ARP for the default gateway',
  desc: 'A freshly booted host has a MAC address but no IP. DHCP gives it an address, mask, gateway and DNS servers; ARP then finds the gateway MAC so the first packet to the Internet can leave. Gratuitous ARP is how virtual IPs move on failover.',
  actors: [
    { id: 'h', label: 'New host', sub: 'MAC …:05, no IP yet', icon: '💻', color: 'gray' },
    { id: 'sw', label: 'Switch / VLAN', sub: 'one broadcast domain', icon: '🔀', color: 'orange', info: 'A switch learns which MAC lives behind which port from the source address of every frame. Broadcasts (destination ff:ff:ff:ff:ff:ff) and unknown destinations are flooded to every port in the VLAN.' },
    { id: 'd', label: 'DHCP server', sub: 'or relay on router', icon: '🗂️', color: 'purple', info: 'Often a relay ("ip helper") on the router converts the broadcast into unicast to a central DHCP server in another subnet. Cloud VPCs run DHCP for you (DHCP option sets in AWS).' },
    { id: 'gw', label: 'Default gateway', sub: '10.0.0.1', icon: '🛜', color: 'blue' },
  ],
  steps: [
    { section: 'DHCP: DORA over UDP 67/68' },
    { from: 'h', to: 'sw', label: 'DISCOVER (broadcast)', caption: 'The host has no address, so it sends from 0.0.0.0:68 to 255.255.255.255:67 with destination MAC ff:ff:ff:ff:ff:ff. The switch learns the host MAC and floods the frame across the VLAN.' },
    { from: 'sw', to: 'd', label: 'flooded DISCOVER', caption: 'Every device in the broadcast domain receives it; only DHCP servers (or a relay agent) act on it. This is why DHCP needs a relay to cross subnets: broadcasts are not routed.' },
    { from: 'd', to: 'h', label: 'OFFER 10.0.0.5/20', reply: true, caption: 'The server proposes an address plus options: subnet mask, default gateway (router option), DNS servers and the lease time. Several servers may offer at once.' },
    { from: 'h', to: 'sw', label: 'REQUEST (broadcast)', caption: 'The host broadcasts which offer it accepts, so any other server that made an offer can release its proposed address.' },
    { from: 'd', to: 'h', label: 'ACK, lease 24 h', reply: true, caption: 'The lease is confirmed. The host renews at half the lease time (T1) by unicast; if the server is gone it rebinds by broadcast at 87.5% (T2).' },
    { from: 'h', to: 'h', label: 'probe + announce', caption: 'Before using the address the host sends an ARP probe to detect duplicates, then a gratuitous ARP announcing "10.0.0.5 is at my MAC" so neighbours refresh their caches.' },
    { section: 'ARP: who has the gateway?' },
    { from: 'h', to: 'sw', label: 'who-has 10.0.0.1?', caption: 'To reach 8.8.8.8 the routing table says "default via 10.0.0.1". The host never ARPs for the remote server, only for the next hop, so it broadcasts an ARP request for the gateway.' },
    { from: 'sw', to: 'gw', label: 'flooded ARP request', caption: 'Every host on the segment sees the request; only the owner of 10.0.0.1 answers. In IPv6 the same job is done by NDP Neighbor Solicitation to a multicast address.' },
    { from: 'gw', to: 'h', label: '10.0.0.1 is-at …:01 (unicast)', reply: true, caption: 'The reply is unicast. The host caches it in its neighbour table (ip neigh): REACHABLE, then STALE after a while, re-validated on use.' },
    { from: 'h', to: 'gw', label: 'frame: dst MAC gw, dst IP 8.8.8.8', caption: 'The first real packet leaves: the Ethernet destination is the gateway MAC while the IP destination is the remote server. L2 addresses change every hop; IP addresses do not (without NAT).' },
    { section: 'Failover and abuse' },
    { from: 'gw', to: 'sw', label: 'GARP: VIP at new MAC', caption: 'With VRRP/keepalived or MetalLB L2 mode, the node taking over a virtual IP broadcasts gratuitous ARP so every cache now points the VIP at its MAC. Works only inside one L2 domain; clouds block it.' },
    { from: 'sw', to: 'h', label: 'forged ARP replies?', caption: 'ARP has no authentication: an attacker on the LAN can claim the gateway IP and become a man in the middle. Switches defend with DHCP snooping plus dynamic ARP inspection; TLS makes intercepted traffic useless.' },
  ],
});

registerDiagram({
  id: 'net-lpm-routing',
  roadmap: 'networking', module: 2, topic: 'Routing Tables, Default Gateway & Longest-Prefix Match',
  kind: 'graph',
  title: 'Longest-prefix match: the most specific matching route wins',
  desc: 'The kernel compares a destination against every route, keeps the ones that contain it, and picks the longest prefix. Order in the table does not matter. The same rule drives VPC route tables, Kubernetes pod routes and BGP hijacks.',
  groups: [
    { id: 'rt', label: 'Main routing table (ip route)', x: 2, y: 0, w: 2.25, h: 5, color: 'blue' },
  ],
  nodes: [
    { id: 'pkt', label: 'Packet', sub: 'dst 10.244.3.9', icon: '📦', x: 0, y: 2, color: 'gray', info: 'Ask the kernel which route it would use with: ip route get 10.244.3.9. The answer shows the next hop, the outgoing interface and the source address it will pick.' },
    { id: 'r0', label: '0.0.0.0/0', sub: 'via 10.0.0.1 (default)', x: 2.125, y: 0.4, w: 2, color: 'blue', info: 'The default route matches every IPv4 address, so it only wins when nothing more specific matches. Its next hop is the default gateway; in a public VPC subnet it points at the Internet gateway, in a private one at a NAT gateway.' },
    { id: 'r1', label: '10.0.0.0/20', sub: 'dev eth0 (connected)', x: 2.125, y: 1.55, w: 2, color: 'blue', info: 'Connected routes are created automatically for each interface subnet. Destinations in them are delivered directly: ARP for the destination itself, no gateway involved. 10.0.0.0/20 covers 10.0.0.0 to 10.0.15.255.' },
    { id: 'r2', label: '10.244.0.0/16', sub: 'via 10.0.0.50', x: 2.125, y: 2.7, w: 2, color: 'blue' },
    { id: 'r3', label: '10.244.3.0/24', sub: 'via 10.0.0.60', x: 2.125, y: 3.85, w: 2, color: 'blue', info: 'A more specific route, for example a pod CIDR advertised by Calico or Cilium over BGP for one node, or a static route to a firewall appliance. More specific always beats less specific, wherever it appears in the table.' },
    { id: 'gw', label: 'Default gateway', sub: '10.0.0.1 → Internet', x: 5.5, y: 0.4, w: 1.5, color: 'gray' },
    { id: 'lan', label: 'Same subnet', sub: 'ARP the host directly', x: 5.5, y: 1.55, w: 1.5, color: 'gray' },
    { id: 'n50', label: 'Node 10.0.0.50', sub: 'pod CIDR /16 summary', x: 5.5, y: 2.7, w: 1.5, color: 'gray' },
    { id: 'n60', label: 'Node 10.0.0.60', sub: 'owns 10.244.3.0/24', x: 5.5, y: 3.85, w: 1.5, color: 'green' },
  ],
  edges: [
    { from: 'pkt', to: 'r0' }, { from: 'pkt', to: 'r1' }, { from: 'pkt', to: 'r2' }, { from: 'pkt', to: 'r3' },
    { from: 'r0', to: 'gw' }, { from: 'r1', to: 'lan' }, { from: 'r2', to: 'n50' }, { from: 'r3', to: 'n60' },
  ],
  steps: [
    { caption: 'A packet for 10.244.3.9 needs a next hop. The kernel checks every route in the table; their order is irrelevant, unlike firewall rules.', active: ['pkt', 'rt'] },
    { caption: 'Three routes contain the address: the /0 default, 10.244.0.0/16 and 10.244.3.0/24. 10.0.0.0/20 does not, because it ends at 10.0.15.255.', flows: [{ from: 'pkt', to: 'r0', label: 'matches /0' }, { from: 'pkt', to: 'r2', label: 'matches /16' }, { from: 'pkt', to: 'r3', label: 'matches /24' }] },
    { caption: 'The longest prefix wins: /24 is more specific than /16 and /0, so the packet goes to node 10.0.0.60. ip route get 10.244.3.9 would print "via 10.0.0.60 dev eth0".', flows: [{ from: 'r3', to: 'n60', label: 'next hop .60', color: 'green' }] },
    { caption: 'Only when prefixes are equal do tie-breakers apply: administrative distance (which source to trust), then metric. Equal-cost routes are used together, and ECMP hashes each flow (5-tuple) to one of them.', active: ['r2', 'r3'] },
    { caption: 'A packet for 8.8.8.8 matches only the default route, so it goes to the default gateway. That is the entire meaning of "default gateway": the next hop of the least specific route.', flows: [{ from: 'pkt', to: 'r0', label: 'dst 8.8.8.8' }, { from: 'r0', to: 'gw', label: 'via 10.0.0.1' }] },
    { caption: 'A packet for 10.0.5.7 hits the connected /20 route: no gateway, the host ARPs for 10.0.5.7 directly. Off-subnet traffic is the only traffic that needs the gateway MAC.', flows: [{ from: 'pkt', to: 'r1', label: 'dst 10.0.5.7' }, { from: 'r1', to: 'lan', label: 'ARP + deliver' }] },
    { caption: 'The same rule is the BGP hijack mechanism: whoever announces a more specific prefix attracts the traffic worldwide. It also explains overlapping-CIDR bugs, where a local /16 (say docker0) silently beats the VPN route.', active: ['r3', 'r2', 'r0'] },
  ],
});

