registerDiagram({
  id: 'net-http-etag',
  roadmap: 'networking', module: 4, topic: 'HTTP Caching: Cache-Control, ETag & Revalidation',
  kind: 'sequence',
  title: 'Browser cache, CDN cache and origin: freshness, ETag and 304',
  desc: 'The origin replies with Cache-Control: max-age=60, s-maxage=300 and ETag "v1". The browser may reuse it for 60 s, the CDN for 300 s; after that, validators make revalidation cheap.',
  actors: [
    { id: 'b', label: 'Browser', sub: 'private cache', icon: '🌐', color: 'blue', info: 'A private cache: it may store responses marked private. max-age applies here; s-maxage is ignored by browsers.' },
    { id: 'cdn', label: 'CDN edge', sub: 'shared cache', icon: '🗄️', color: 'orange', info: 'A shared cache: s-maxage overrides max-age here. It must never store responses marked private or no-store, and stores responses to requests with Authorization only if the response explicitly allows it (public, s-maxage).' },
    { id: 'o', label: 'Origin', sub: 'app server', icon: '🖥️', color: 'green' },
  ],
  steps: [
    { section: 'Cold caches' },
    { from: 'b', to: 'cdn', label: 'GET /products/42', caption: 'Nothing is cached anywhere yet.' },
    { from: 'cdn', to: 'o', label: 'GET /products/42', caption: 'Cache miss at the edge, so the CDN forwards the request.' },
    { from: 'o', to: 'cdn', label: '200, ETag "v1"', reply: true, caption: 'Cache-Control: max-age=60, s-maxage=300 plus ETag "v1", a validator that identifies this version of the body.' },
    { from: 'cdn', to: 'b', label: '200, ETag "v1"', reply: true, caption: 'The CDN stores it for 300 s and adds an Age header; the browser stores it for 60 s minus Age.' },
    { section: 'Fresh: no request at all' },
    { from: 'b', to: 'b', label: 'age < 60 s: reuse', caption: 'While fresh, the browser uses its copy with zero network traffic. Fingerprinted assets go further with max-age=31536000, immutable.' },
    { section: 'Stale in the browser: revalidate' },
    { from: 'b', to: 'cdn', label: 'If-None-Match: "v1"', caption: 'After 60 s the copy is stale but still useful: the browser sends a conditional request with its ETag. (no-cache means do this on every use; no-store means never store.)' },
    { from: 'cdn', to: 'b', label: '304 Not Modified', reply: true, caption: 'The CDN copy is still fresh and the ETag matches, so it answers 304 with no body: a few hundred bytes instead of the full payload. The browser marks its copy fresh again.' },
    { section: 'Stale in the CDN, content changed' },
    { from: 'cdn', to: 'o', label: 'If-None-Match: "v1"', caption: 'After 300 s the CDN revalidates with the origin. With stale-while-revalidate it can keep serving the old copy to users while this happens in the background.' },
    { from: 'o', to: 'cdn', label: '200, ETag "v2"', reply: true, caption: 'The product changed, so the origin sends the full new body with a new ETag. Had nothing changed, a 304 would refresh the CDN copy cheaply.' },
    { from: 'cdn', to: 'b', label: '200, ETag "v2"', reply: true, caption: 'The browser replaces its copy. Vary decides which request headers are part of the cache key; Vary: Cookie would destroy the hit ratio.' },
    { section: 'Writes: optimistic concurrency' },
    { from: 'b', to: 'o', label: 'PUT If-Match: "v1"', caption: 'The same ETag protects writes: "apply this only if the resource is still v1".' },
    { from: 'o', to: 'b', label: '412 Precondition Failed', reply: true, caption: 'Someone else already changed it to v2, so the update is rejected instead of silently overwriting their change (the lost-update problem). The client re-reads and retries.' },
  ],
});

registerDiagram({
  id: 'net-cors-preflight',
  roadmap: 'networking', module: 4, topic: 'Cookies & CORS',
  kind: 'sequence',
  title: 'CORS: preflight, credentialed request, and what CORS does not protect',
  desc: 'A page on app.example.com calls api.example.com. The browser, not the server, enforces CORS: it decides whether the page script may read the response. That is why curl "works" while the browser shows a CORS error.',
  actors: [
    { id: 'js', label: 'Page script', sub: 'app.example.com', icon: '📜', color: 'purple' },
    { id: 'br', label: 'Browser', sub: 'enforces same-origin', icon: '🌐', color: 'blue', info: 'An origin is scheme + host + port. app.example.com and api.example.com are different origins, so the same-origin policy applies even though they share a parent domain.' },
    { id: 'api', label: 'API', sub: 'api.example.com', icon: '🖥️', color: 'green' },
  ],
  steps: [
    { section: 'Preflight for a non-simple request' },
    { from: 'js', to: 'br', label: 'fetch PUT /orders', caption: 'PUT with a JSON body, an Authorization header and credentials: "include". Any of these makes it non-simple, so the browser must ask permission first.' },
    { from: 'br', to: 'api', label: 'OPTIONS /orders', caption: 'The preflight carries Origin, Access-Control-Request-Method: PUT and Access-Control-Request-Headers: authorization, content-type. It has no cookies and no body.' },
    { from: 'api', to: 'br', label: '204 + Allow-* headers', reply: true, caption: 'Allow-Origin must echo https://app.example.com (not * when credentials are used), plus Allow-Methods, Allow-Headers, Allow-Credentials: true and Max-Age to cache the preflight.' },
    { from: 'br', to: 'br', label: 'check + cache', caption: 'The browser checks every requested method and header against the answer. If anything is missing, the real request is never sent.' },
    { section: 'The actual request' },
    { from: 'br', to: 'api', label: 'PUT /orders + Cookie', caption: 'Now the real request goes out with cookies (subject to SameSite) and the Origin header.' },
    { from: 'api', to: 'br', label: '200 + ACAO, Vary', reply: true, caption: 'The response must again carry Access-Control-Allow-Origin and Allow-Credentials. Vary: Origin stops a shared cache from serving the CORS headers meant for one origin to another.' },
    { from: 'br', to: 'js', label: 'response readable', reply: true, caption: 'Only now does the script see the status and body.' },
    { section: 'Simple request, misconfigured server' },
    { from: 'js', to: 'br', label: 'fetch POST (form)', caption: 'A POST with a form content type and no custom headers is a simple request: no preflight.' },
    { from: 'br', to: 'api', label: 'POST /orders', caption: 'It reaches the server and is executed. CORS controls who may read responses, not who may send requests, so CSRF needs SameSite cookies or tokens, and authorization must live on the server.' },
    { from: 'api', to: 'br', label: '200 (no ACAO)', reply: true, caption: 'The server forgot the CORS headers.' },
    { from: 'br', to: 'js', label: 'TypeError: CORS', reply: true, caption: 'The browser hides the response from the script. curl and server-to-server calls ignore CORS entirely, which is why "it works in curl" proves nothing here.' },
  ],
});

registerDiagram({
  id: 'net-websocket-upgrade',
  roadmap: 'networking', module: 4, topic: 'Real-Time: WebSockets, Server-Sent Events & Long Polling',
  kind: 'sequence',
  title: 'WebSocket lifecycle: HTTP Upgrade, frames, heartbeats and drain',
  desc: 'A WebSocket starts as an ordinary HTTP/1.1 request through every proxy on the path, then becomes a long-lived full-duplex channel. Most production problems are proxy configuration, idle timeouts and fan-out across instances.',
  actors: [
    { id: 'b', label: 'Browser', sub: 'new WebSocket(url)', icon: '🌐', color: 'gray' },
    { id: 'p', label: 'Nginx / LB', sub: 'reverse proxy', icon: '⚖️', color: 'orange', info: 'Upgrade and Connection are hop-by-hop headers: a proxy consumes them unless it is told to pass them on. Nginx needs proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade and Connection "upgrade". AWS ALB and Envoy support WebSockets natively.' },
    { id: 'a', label: 'App server', sub: 'Go, gorilla / coder ws', icon: '⚙️', color: 'green' },
    { id: 'r', label: 'Pub/sub', sub: 'Redis / NATS', icon: '📣', color: 'purple', info: 'Each connection lives on exactly one app instance, so a message produced on instance 2 must reach users connected to instance 7. A pub/sub backbone (Redis, NATS, Kafka) fans it out to whichever instances hold the subscribers.' },
  ],
  steps: [
    { section: 'Upgrade handshake (HTTP/1.1)' },
    { from: 'b', to: 'p', label: 'GET /ws, Upgrade', caption: 'A normal GET with Connection: Upgrade, Upgrade: websocket, a random Sec-WebSocket-Key and Sec-WebSocket-Version: 13. Cookies are sent automatically, so the server must check Origin to stop cross-site WebSocket hijacking.' },
    { from: 'p', to: 'a', label: 'pass Upgrade hdrs', caption: 'The proxy must forward the hop-by-hop Upgrade and Connection headers. If it does not, the app sees a plain GET and answers 400 or 426: the classic "works locally, fails behind Nginx".' },
    { from: 'a', to: 'p', label: '101 Switching', reply: true, caption: 'The server answers 101 with Sec-WebSocket-Accept = base64(SHA-1(key + fixed GUID)), proving it really speaks WebSocket rather than being a cache replaying a response.' },
    { from: 'p', to: 'b', label: '101 + Accept', reply: true, caption: 'From now on the TCP connection (and the proxy connection pair) carries WebSocket frames, not HTTP. Over HTTP/2 or HTTP/3 the same thing is done with extended CONNECT (RFC 8441, RFC 9220).' },
    { section: 'Full-duplex messages' },
    { from: 'b', to: 'a', label: 'text frame (masked)', caption: 'Frames carry a FIN bit, an opcode (text, binary, ping, pong, close) and a length. Client-to-server frames are XOR-masked so that naive intermediaries cannot be tricked into cache poisoning.' },
    { from: 'a', to: 'r', label: 'SUBSCRIBE room:42', caption: 'The app registers interest in the topics this connection cares about.' },
    { from: 'r', to: 'a', label: 'msg from other pod', reply: true, caption: 'A message published by any instance arrives here because this instance holds the subscriber. Without pub/sub, users on different instances could not talk to each other.' },
    { from: 'a', to: 'b', label: 'server push frame', reply: true, caption: 'The server pushes whenever it wants: no polling, no request per message. If traffic is only server to client, SSE is simpler and works over plain HTTP.' },
    { section: 'Keeping it alive' },
    { from: 'a', to: 'b', label: 'ping every 25 s', caption: 'Quiet connections are killed by idle timeouts on every hop (ALB 60 s, Nginx proxy_read_timeout 60 s, NAT gateways 350 s). Heartbeats must be more frequent than the shortest timeout.' },
    { from: 'b', to: 'a', label: 'pong (automatic)', reply: true, caption: 'Browsers answer pings automatically. A missing pong lets the server detect half-open connections, for example a phone that silently lost coverage.' },
    { from: 'p', to: 'p', label: 'idle 60 s: close', caption: 'Without heartbeats the proxy closes the connection after its idle timeout, and the browser reports close code 1006 (abnormal closure) with no close frame.' },
    { section: 'Deploys' },
    { from: 'a', to: 'b', label: 'close 1001 going away', caption: 'On SIGTERM the server sends a close frame with code 1001 and drains gradually instead of dropping thousands of sockets at once.' },
    { from: 'b', to: 'p', label: 'reconnect + last id', caption: 'Clients reconnect with exponential backoff plus jitter (avoiding a thundering herd), land on another instance and resume from the last message id they saw.' },
  ],
});

