registerDiagram({
  id: 'net-dns-resolution',
  roadmap: 'networking', module: 5, topic: 'How Resolution Works: Stub → Recursive → Root → TLD → Authoritative',
  kind: 'sequence',
  title: 'Resolving api.example.com from a cold cache',
  desc: 'The stub in your process asks one recursive resolver; the recursive resolver does the iterative walk down the hierarchy, following referrals, and caches every answer for its TTL.',
  actors: [
    { id: 'stub', label: 'App + stub', sub: 'getaddrinfo()', icon: '⚙️', color: 'gray', info: 'The stub resolver (libc or the Go resolver) reads /etc/resolv.conf for the resolver address and search domains. The Go standard resolver does not cache; the JVM caches according to networkaddress.cache.ttl.' },
    { id: 'res', label: 'Recursive resolver', sub: 'VPC +2, 1.1.1.1',color: 'blue', info: 'Does all the work and holds the shared cache. In AWS it is the VPC resolver at the VPC base +2 (or 169.254.169.253); in Kubernetes pods talk to CoreDNS, which forwards to it.' },
    { id: 'root', label: 'Root server', sub: 'a–m, anycast', icon: '🌍', color: 'purple', info: '13 named identities (a to m) served by well over a thousand anycast instances. Root servers only know who runs each TLD.' },
    { id: 'tld', label: '.com TLD server', sub: 'gTLD servers', icon: '🏷️', color: 'orange' },
    { id: 'auth', label: 'Authoritative', sub: 'Route 53: example.com', icon: '📒', color: 'green', info: 'Holds the zone and answers with the AA (authoritative answer) flag. This is where GeoDNS, weighted and failover routing policies are applied.' },
  ],
  steps: [
    { from: 'stub', to: 'stub', label: 'hosts file, cache', caption: 'The stub checks /etc/hosts (order set by nsswitch.conf) and any local cache such as systemd-resolved. Nothing found.' },
    { from: 'stub', to: 'res', label: 'A? api.example.com', caption: 'A recursive query (RD bit set) over UDP 53: "give me the final answer, do the work for me".' },
    { from: 'res', to: 'res', label: 'cache miss', caption: 'A cold cache. Normally the .com referral and often the final answer are already cached, which is why most lookups take a few milliseconds.' },
    { from: 'res', to: 'root', label: 'A? api.example.com', caption: 'Iterative queries from here on: the resolver asks each server and follows referrals itself.' },
    { from: 'root', to: 'res', label: 'referral: .com NS', reply: true, caption: 'The root does not know the answer but knows the .com servers: NS records plus glue A/AAAA records so the resolver can reach them.' },
    { from: 'res', to: 'tld', label: 'A? api.example.com', caption: 'Same question to a .com TLD server.' },
    { from: 'tld', to: 'res', label: 'referral: NS + glue', reply: true, caption: 'Referral to the authoritative servers for example.com (for example ns-123.awsdns-15.com). Glue breaks the chicken-and-egg problem when name servers live inside the zone they serve.' },
    { from: 'res', to: 'auth', label: 'A? api.example.com', caption: 'Finally the server that owns the zone.' },
    { from: 'auth', to: 'res', label: 'CNAME my-alb-123.us-east-1.elb.amazonaws.com (AA)', reply: true, caption: 'An authoritative answer: a CNAME to the load balancer name. Route 53 alias records avoid this extra hop by returning the A records directly.' },
    { from: 'res', to: 'res', label: 'chase CNAME → A', caption: 'The resolver resolves the CNAME target the same way (usually from cache), then caches every record for its own TTL.' },
    { from: 'res', to: 'stub', label: 'A 52.20.1.7, TTL 60', reply: true, caption: 'The stub gets the final address. Every layer (browser, OS, node cache, resolver) may keep it until the TTL expires, which is why DNS changes are not instant.' },
    { section: 'Large answer: truncation and TCP' },
    { from: 'res', to: 'auth', label: 'TXT? example.com', caption: 'Some answers are big: many TXT records, DNSSEC signatures, long record sets.' },
    { from: 'auth', to: 'res', label: 'TC=1 (truncated)', reply: true, caption: 'If the answer exceeds the advertised EDNS0 buffer (1232 bytes is the recommended value since DNS Flag Day 2020), the server sets the TC bit.' },
    { from: 'res', to: 'auth', label: 'same query over TCP 53', caption: 'The resolver retries over TCP. Firewalls and security groups that allow only UDP 53 break exactly these lookups.' },
  ],
});

