registerDiagram({
  id: 'net-cdn-shield',
  roadmap: 'networking', module: 8, topic: 'Origin Shielding & Request Collapsing',
  kind: 'graph',
  title: 'A hot object expires everywhere: origin shield + request collapsing',
  desc: 'A popular object expires (or is purged) at every PoP at the same moment. Without protection every PoP, and every server inside it, asks the origin. A shield tier plus request collapsing turns that stampede into one origin fetch.',
  groups: [
    { id: 'cdn', label: 'CDN', x: 2, y: 0, w: 3, h: 5, color: 'orange' },
  ],
  nodes: [
    { id: 'u1', label: 'Users: Paris', icon: '👥', x: 0, y: 0, color: 'gray' },
    { id: 'u2', label: 'Users: Tokyo', icon: '👥', x: 0, y: 2, color: 'gray' },
    { id: 'u3', label: 'Users: Brazil', icon: '👥', x: 0, y: 4, color: 'gray' },
    { id: 'p1', label: 'Edge PoP CDG', sub: 'cache miss', x: 2, y: 0, color: 'orange' },
    { id: 'p2', label: 'Edge PoP NRT', sub: 'cache miss', x: 2, y: 2, color: 'orange' },
    { id: 'p3', label: 'Edge PoP GRU', sub: 'cache miss', x: 2, y: 4, color: 'orange' },
    { id: 'sh', label: 'Origin shield', sub: 'one tier near origin', x: 4, y: 2, color: 'purple', info: 'A designated PoP or tier (CloudFront Origin Shield, Fastly shielding, Cloudflare Tiered Cache) that all edge misses go through. It also raises hit ratio for long-tail objects that each edge sees too rarely to keep cached.' },
    { id: 'or', label: 'Origin', sub: 'app + database', icon: '🖥️', x: 6, y: 2, color: 'green', info: 'Capacity-plan the origin for cold-cache scenarios (after a global purge, a new release, a cache eviction wave), not only for the steady-state hit ratio. Lock it down so only the CDN can reach it.' },
  ],
  edges: [
    { from: 'u1', to: 'p1' }, { from: 'u2', to: 'p2' }, { from: 'u3', to: 'p3' },
    { from: 'p1', to: 'sh' }, { from: 'p2', to: 'sh' }, { from: 'p3', to: 'sh' },
    { from: 'sh', to: 'or' },
  ],
  steps: [
    { caption: 'Requests for /hot.jpg arrive at PoPs worldwide just after it expired or was purged. Every PoP misses at the same moment.', flows: [{ from: 'u1', to: 'p1', label: 'GET /hot.jpg' }, { from: 'u2', to: 'p2', label: 'GET /hot.jpg' }, { from: 'u3', to: 'p3', label: 'GET /hot.jpg' }] },
    { caption: 'Without a shield each PoP would go straight to the origin: 300 PoPs times several cache servers each means hundreds or thousands of identical requests. With a shield, every miss goes to one tier instead.', flows: [{ from: 'p1', to: 'sh', label: 'miss' }, { from: 'p2', to: 'sh', label: 'miss' }, { from: 'p3', to: 'sh', label: 'miss' }] },
    { caption: 'Request collapsing: the first miss for a cache key goes to the origin, and concurrent requests for the same key wait on it (Nginx proxy_cache_lock, Varnish, Go singleflight).', flows: [{ from: 'sh', to: 'or', label: '1 request' }] },
    { caption: 'The origin serves one request per object per TTL from the shield, no matter how many PoPs or users asked.', flows: [{ from: 'or', to: 'sh', label: '200, max-age=300' }] },
    { caption: 'All waiting requests get the same response, and each tier stores it according to its cache rules.', flows: [{ from: 'sh', to: 'p1', label: 'fill' }, { from: 'sh', to: 'p2', label: 'fill' }, { from: 'sh', to: 'p3', label: 'fill' }] },
    { caption: 'Users are served, and the next requests are edge hits. The shield also keeps long-tail objects that individual edges would have evicted, which raises the overall hit ratio.', flows: [{ from: 'p1', to: 'u1', label: 'HIT next time' }, { from: 'p2', to: 'u2', label: 'served' }, { from: 'p3', to: 'u3', label: 'served' }] },
    { caption: 'Add stale-while-revalidate so users get the stale copy instantly while one background request refreshes it, and stale-if-error so an origin outage becomes stale content instead of downtime. Never cache 5xx for long.', flows: [{ from: 'sh', to: 'or', label: 'refresh (bg)' }], active: ['p1', 'p2', 'p3'] },
  ],
});

