registerDiagram({
  id: 'net-dmz-nat',
  roadmap: 'networking', module: 9, topic: 'NAT Is Not Security; Segmentation & DMZ',
  kind: 'graph',
  title: 'Tiered subnets in a VPC, and why NAT is not a firewall',
  desc: 'The cloud version of a DMZ: only the load balancer and NAT gateway sit in public subnets, apps are private, data is isolated. Security groups reference each other. Then watch what NAT does and does not stop.',
  groups: [
    { id: 'pub', label: 'Public (DMZ)', x: 1.75, y: 0, w: 1.25, h: 4, color: 'orange' },
    { id: 'priv', label: 'Private app', x: 3.75, y: 0, w: 1.25, h: 4, color: 'blue' },
    { id: 'data', label: 'Isolated data', x: 5.75, y: 0, w: 1.25, h: 4, color: 'teal' },
  ],
  nodes: [
    { id: 'user', label: 'User', sub: 'HTTPS', icon: '👤', x: 0, y: 0.5, color: 'gray' },
    { id: 'ext', label: 'Internet host', sub: 'API, attacker or C2', icon: '🌐', x: 0, y: 3, color: 'red' },
    { id: 'alb', label: 'ALB + WAF', sub: 'only public entry', x: 1.75, y: 0.5, w: 1.25, color: 'orange', info: 'In the cloud, the public subnet should contain only load balancers, WAF endpoints and NAT gateways. Admin access goes through SSM Session Manager, IAP or Teleport, with no inbound SSH open at all.' },
    { id: 'nat', label: 'NAT gateway', sub: 'egress only', x: 1.75, y: 3, w: 1.25, color: 'orange' },
    { id: 'app', label: 'App servers', sub: 'private IPs only', x: 3.75, y: 1.75, w: 1.25, color: 'blue', info: 'Security group app-sg allows 8080 only from alb-sg. Referencing security groups instead of CIDRs means the rule follows the instances as they scale: micro-segmentation by role.' },
    { id: 'db', label: 'Database', sub: 'no internet route', x: 5.75, y: 1.75, w: 1.25, shape: 'db', color: 'teal', info: 'db-sg allows 5432 only from app-sg. The data subnet route table has no 0.0.0.0/0 route at all, so even a compromised database host cannot reach the Internet.' },
  ],
  edges: [
    { from: 'user', to: 'alb', label: 'HTTPS 443' },
    { from: 'alb', to: 'app', label: 'SG: from alb-sg' },
    { from: 'app', to: 'db', label: 'SG: 5432 from app-sg' },
    { from: 'app', to: 'nat', label: 'egress' },
    { from: 'nat', to: 'ext', label: 'SNAT' },
  ],
  steps: [
    { caption: 'Only the load balancer has a public address. It terminates TLS, runs WAF rules, and is the single way in: the modern equivalent of the DMZ between an outer and an inner firewall.', flows: [{ from: 'user', to: 'alb', label: 'GET /checkout' }] },
    { caption: 'App servers accept traffic only from the load balancer security group. There is no route from the Internet to their private IPs.', flows: [{ from: 'alb', to: 'app', label: 'to :8080' }] },
    { caption: 'The database accepts only the app security group on 5432, and its subnet has no Internet route. Each tier limits the blast radius of a breach in the tier above.', flows: [{ from: 'app', to: 'db', label: 'SQL' }] },
    { caption: 'Apps reach third-party APIs and package mirrors through the NAT gateway. Replies are matched to the outbound connection and let back in.', flows: [{ from: 'app', to: 'nat', label: 'GET api' }, { from: 'nat', to: 'ext', label: 'src = NAT IP' }] },
    { caption: 'An unsolicited inbound SYN to the NAT IP is dropped because no translation entry matches. That protection comes from connection state tracking, which a stateful firewall provides explicitly, not from hiding addresses.', flows: [{ from: 'ext', to: 'nat', label: 'SYN: dropped', color: 'red' }] },
    { caption: 'But a compromised app can connect out freely: NAT happily translates data exfiltration and command-and-control callbacks. Egress control (allow-lists, FQDN policies, an egress proxy, DNS filtering) is what stops this.', flows: [{ from: 'app', to: 'nat', label: 'stolen data', color: 'red' }, { from: 'nat', to: 'ext', label: 'allowed!', color: 'red' }] },
    { caption: 'With IPv6 there is no NAT and every host is globally addressable, so you need what you should have had anyway: stateful default-deny inbound (security groups, an egress-only Internet gateway). Treat NAT as address conservation.', active: ['app', 'alb', 'nat', 'pub', 'priv'] },
  ],
});

registerDiagram({
  id: 'net-ddos-layers',
  roadmap: 'networking', module: 9, topic: 'DDoS Attack Types & Mitigation',
  kind: 'graph',
  title: 'DDoS defence in layers: volumetric, protocol and application attacks',
  desc: 'Each attack class is stopped at a different layer. Volume is absorbed by anycast capacity, protocol attacks by stateless filtering and SYN cookies, application floods by WAF and rate limits, and the origin is locked so attackers cannot go around the edge.',
  groups: [
    { id: 'edge', label: 'Anycast CDN / DDoS provider', x: 2, y: 1.5, w: 3, h: 1.5, color: 'blue' },
    { id: 'ovpc', label: 'Origin VPC', x: 6, y: 1.5, w: 1, h: 1.5, color: 'green' },
  ],
  nodes: [
    { id: 'bot', label: 'Botnet', sub: '100k hijacked hosts', icon: '🤖', x: 0, y: 0, color: 'red' },
    { id: 'refl', label: 'Open resolvers', sub: 'reflectors, UDP 53', x: 0, y: 2, color: 'red', info: 'Open DNS resolvers, NTP servers (monlist), memcached (up to ~50,000x), CLDAP and SSDP turn a small spoofed request into a large reply. Fixes on the Internet side: BCP 38 source address validation, closing open reflectors, response rate limiting.' },
    { id: 'user', label: 'Real users', icon: '👥', x: 0, y: 4, color: 'gray' },
    { id: 'l34', label: 'L3/L4 scrubbing', sub: 'XDP, SYN cookies', x: 2, y: 2, color: 'blue', info: 'Runs at every PoP: drops unexpected protocols and source ports in XDP/eBPF before the kernel stack, answers SYNs with SYN cookies or a SYN proxy, and filters statelessly before any stateful device whose conntrack table could be exhausted.' },
    { id: 'waf', label: 'WAF + rate limit', sub: 'bot score, challenge', x: 4, y: 2, color: 'blue', info: 'Per IP, key or TLS fingerprint rate limits, managed rules, bot scoring and JavaScript or managed challenges. Caching also helps: a cached response costs almost nothing to serve during a flood.' },
    { id: 'or', label: 'Origin', sub: 'allowlists CDN only', icon: '🖥️', x: 6, y: 2, color: 'green', info: 'Accept traffic only from the CDN: published IP ranges or a managed prefix list, authenticated origin pulls (mTLS), or an outbound-only tunnel so the origin has no public IP at all. Set server timeouts such as ReadHeaderTimeout in Go to defeat Slowloris.' },
  ],
  edges: [
    { from: 'bot', to: 'refl', label: 'spoofed src' },
    { from: 'refl', to: 'l34', label: 'amplified replies' },
    { from: 'bot', to: 'l34', label: 'SYN / HTTP floods' },
    { from: 'user', to: 'l34' },
    { from: 'l34', to: 'waf', label: 'clean traffic' },
    { from: 'waf', to: 'or', label: 'origin pull' },
    { from: 'bot', to: 'or', label: 'direct to origin IP', dashed: true, curve: -60 },
  ],
  steps: [
    { caption: 'Reflection and amplification: bots send small DNS queries with the source address forged to be the victim. Open resolvers send replies tens of times larger to the victim. It works because UDP has no handshake to verify the source.', flows: [{ from: 'bot', to: 'refl', label: 'src = victim IP' }, { from: 'refl', to: 'l34', label: '50x bigger', color: 'red' }] },
    { caption: 'Anycast spreads the flood across every PoP: a 1 Tbps attack over 300 locations is about 3 Gbps each, well within capacity. Unexpected UDP (source port 53 to a web service) is dropped at line rate.', active: ['l34', 'edge'] },
    { caption: 'Protocol attacks target state, not bandwidth: a SYN flood tries to fill SYN queues and conntrack tables. SYN cookies and stateless filtering in front of stateful devices keep the edge alive; the origin never sees it.', flows: [{ from: 'bot', to: 'l34', label: 'SYN flood', color: 'red' }] },
    { caption: 'Application floods look like real requests: GET /login or /search a million times, slow headers (Slowloris), HTTP/2 Rapid Reset. They pass L3/L4 and are stopped by WAF rules, rate limits, bot challenges and caching.', flows: [{ from: 'bot', to: 'l34', label: 'GET /login x1M', color: 'red' }, { from: 'l34', to: 'waf', label: 'looks valid' }] },
    { caption: 'Real users pass every layer. The edge keeps warm, authenticated connections to the origin, so even uncacheable traffic benefits.', flows: [{ from: 'user', to: 'l34', label: 'GET /' }, { from: 'l34', to: 'waf', label: 'clean' }, { from: 'waf', to: 'or', label: 'origin pull' }] },
    { caption: 'Attackers who find the origin IP try to bypass the edge. An origin that only accepts CDN ranges or mTLS pulls (or has no public IP at all) drops them. Never leak the origin IP in DNS history, mail headers or certificates.', flows: [{ from: 'bot', to: 'or', label: 'blocked', color: 'red' }] },
    { caption: 'Finally, make expensive endpoints cheap to reject (validate and authenticate at the edge), set aggressive server timeouts, enforce per-tenant quotas and keep an "under attack" runbook ready before you need it.', active: ['waf', 'or'] },
  ],
});

registerDiagram({
  id: 'net-conntrack-firewall',
  roadmap: 'networking', module: 9, topic: 'Firewalls: Stateless, Stateful, L7 & WAF',
  kind: 'sequence',
  title: 'Stateful vs stateless filtering: conntrack, return traffic and expiry',
  desc: 'One outbound HTTPS connection from an instance crosses a stateful security group and a stateless network ACL. Watch which device needs an explicit rule for the replies, why unsolicited traffic is dropped, and what happens when state expires.',
  actors: [
    { id: 'app', label: 'App instance', sub: '10.20.1.15', icon: '🖥️', color: 'blue' },
    { id: 'sg', label: 'Security group', sub: 'stateful (conntrack)', icon: '🛡️', color: 'green', info: 'Allow-only rules evaluated for the first packet of a flow. Allowed flows get a tracking entry keyed by the 5-tuple, and every later packet in either direction matches the entry instead of the rules. Linux iptables/nftables with ct state works the same way.' },
    { id: 'nacl', label: 'Network ACL', sub: 'stateless, subnet edge', icon: '🚧', color: 'orange', info: 'Numbered allow and deny rules, first match wins, evaluated for every packet in each direction independently. It has no idea that a packet is a reply to something you sent.' },
    { id: 'srv', label: 'Payment API', sub: '52.94.1.10:443', icon: '🌐', color: 'gray' },
    { id: 'att', label: 'Scanner', sub: 'unsolicited traffic', icon: '👾', color: 'red' },
  ],
  steps: [
    { section: 'Outbound: first packet' },
    { from: 'app', to: 'sg', label: 'SYN → :443', caption: 'The app connects from ephemeral port 43122. The security group egress rule allows TCP 443, so the first packet passes.' },
    { from: 'sg', to: 'sg', label: 'entry: NEW', caption: 'conntrack records the flow (src 10.20.1.15:43122, dst 52.94.1.10:443, TCP). From now on this flow skips the rule walk entirely.' },
    { from: 'sg', to: 'nacl', label: 'SYN', caption: 'At the subnet edge the NACL evaluates the packet on its own: outbound rule "allow TCP 443" matches.' },
    { from: 'nacl', to: 'srv', label: 'SYN', caption: 'The packet leaves the subnet (via a NAT or Internet gateway, not shown).' },
    { section: 'Return traffic' },
    { from: 'srv', to: 'nacl', label: 'SYN-ACK → :43122', reply: true, caption: 'The reply is addressed to the ephemeral port. The NACL needs an inbound rule allowing TCP 1024-65535; without it the reply is dropped and the client just sees a connect timeout: the classic NACL bug.' },
    { from: 'nacl', to: 'sg', label: 'SYN-ACK', reply: true, caption: 'With the ephemeral range allowed, the packet reaches the security group.' },
    { from: 'sg', to: 'sg', label: 'matches: ESTAB', caption: 'No inbound rule is needed: the packet matches the tracked flow, which becomes ESTABLISHED. This is the whole point of a stateful firewall.' },
    { from: 'sg', to: 'app', label: 'SYN-ACK', reply: true, caption: 'The handshake completes and data flows in both directions on the same entry.' },
    { section: 'Unsolicited inbound' },
    { from: 'att', to: 'nacl', label: 'SYN → :22', caption: 'A scanner probes SSH. Many NACLs allow all inbound traffic (the default NACL does), so the packet goes on to the security group.' },
    { from: 'nacl', to: 'sg', label: 'SYN → :22', caption: 'The security group sees a NEW flow with no matching inbound rule.' },
    { from: 'sg', to: 'sg', label: 'NEW, no rule: drop', caption: 'Dropped silently. Unsolicited traffic never matches an existing entry, which is also the only reason NAT appears to protect hosts.' },
    { section: 'When state goes away' },
    { from: 'app', to: 'srv', label: 'data after 10 min idle via NAT', caption: 'Each stateful hop has its own idle timeout: AWS NAT gateways and NLBs forget idle TCP after 350 s. The next packet matches no entry, is dropped or reset, and the app hangs. Fix with keep-alives below the shortest timeout.' },
    { from: 'sg', to: 'sg', label: 'asymmetric reply?', caption: 'A reply that returns through a different stateful device (asymmetric routing) has no entry there and is dropped. Rule changes also do not cut flows already tracked until they end.' },
  ],
});

